const state={page:'home',query:'',cat:'全部',tag:'全部',area:'全部',view:'map',selected:'afa',story:'',route:'',step:1,contribution:{type:'',name:'',address:'',tags:[],description:'',contact:''},saved:new Set(JSON.parse(localStorage.getItem('green-go-saved')||'[]')),mobileNav:false,language:'zh',turnstileSiteKey:'',maptilerKey:'',configLoaded:false};
