const logo=()=>`<a class="logo" href="#home" aria-label="綠門 GO 首頁"><span class="logo-mark">${I('leaf',32)}</span><span><strong>綠門<span class="logo-go">GO</span></strong><small>澳門生態地圖</small></span></a>`;
function header(){return `<header class="header"><div class="site-banner" role="img" aria-label="綠門 GO：一起建設一個更公益、永續和諧的共同家園"></div><div class="header-inner">${logo()}<button class="mobile-menu" data-action="menu" aria-label="開啟選單">${I(state.mobileNav?'close':'menu',24)}</button><nav class="nav ${state.mobileNav?'is-open':''}" aria-label="主選單">${[['home','首頁'],['map','地圖'],['routes','主題路線'],['stories','人物故事'],['contribute','參與投稿'],['about','關於我們']].map(([key,label])=>`<a href="#${key}" class="${state.page===key?'active':''}">${label}</a>`).join('')}</nav><div class="header-actions"><button class="icon-button" data-action="search-focus" aria-label="搜尋">${I('search',21)}</button><span class="header-rule"></span><button class="lang-button" data-action="language" aria-label="切換語言">${I('globe',19)} <span>${state.language==='zh'?'中':'EN'}</span></button></div></div></header>`}
function foot(){return `<footer class="footer"><div><div class="footer-brand">${I('leaf',25)} 綠門 GO</div><p>每一個點，都是改變的起點。</p></div><div class="footer-links"><a href="#map">探索地圖</a><a href="#routes">主題路線</a><a href="#contribute">推薦地方</a></div><small>澳門生態地圖</small></footer>`}
function tagChip(t){return `<span class="tag">${t}</span>`}
function catButton(c,active=false){return `<button class="category ${active?'active':''}" data-cat="${c[0]}"><span class="category-icon">${I(c[1],23)}</span><span>${c[0]}</span></button>`}
function searchBox(value='',compact=false){return `<form class="search-box ${compact?'compact':''}" data-search-form><span>${I('search',21)}</span><input name="q" aria-label="搜尋地點或關鍵字" placeholder="搜尋地點、關鍵字或一種生活方式" value="${escapeHtml(value)}"/><button type="submit" aria-label="搜尋">${I('arrow',20)}</button></form>`}
function home(){const featured=places.find(p=>p.id==='afa')||places[0];return `<main class="home"><section class="hero"><div class="hero-image"></div><div class="hero-shade"></div><div class="hero-content"><div class="hero-text"><p class="hero-intro">澳門生態地圖</p><h1>從一個地方，<br><em>遇見更好的日常。</em></h1><p>有人修補舊鞋，有人種下一株菜。沿著地圖走，認識讓澳門慢慢變好的每一個人。</p></div><div class="hero-search">${searchBox()}<div class="hero-hints"><span>今天想從哪裡開始？</span><button data-quick="修">修補日常</button><button data-quick="食">在地滋味</button><button data-quick="去">親近自然</button></div></div></div><div class="hero-caption">沿著生活的足跡，重新認識澳門。</div></section><section class="quick-explore section-wrap"><div class="section-heading"><div><h2>用你的方式，走進這座城</h2><p>從一件小事開始，看見地方與人的連結。</p></div><a class="text-link" href="#map">探索完整地圖 ${I('arrow',18)}</a></div><div class="category-row">${cats.slice(1).map(c=>catButton(c)).join('')}</div></section>${featured?`<section class="featured section-wrap"><div class="featured-photo"><img src="${escapeHtml(featured.img||'assets/shoe-repair.png')}" alt="${escapeHtml(featured.name)}" loading="lazy"><span class="photo-label">街坊故事 · ${escapeHtml(featured.area)}</span></div><div class="featured-copy"><p class="section-count">一個地方，一段故事</p><h2>${escapeHtml(featured.name)}</h2><p>${escapeHtml(featured.desc)}</p><a class="filled-link" href="#place/${encodeURIComponent(featured.id)}">認識這個地方 ${I('arrow',18)}</a></div></section>`:''}<section class="routes-preview section-wrap"><div class="section-heading"><div><h2>把城市走成一段故事</h2><p>從不同角度遇見澳門。</p></div><a class="text-link" href="#routes">全部路線 ${I('arrow',18)}</a></div><div class="route-grid">${routes.slice(0,3).map((r,i)=>routeCard(r,i)).join('')}</div></section></main>`}
function routeCard(r,i){return `<article class="route-card"><div class="route-art route-art-${i+1}"><span>${String(i+1).padStart(2,'0')}</span><div>${I(i===0?'eat':i===1?'tools':'leaf',40)}</div></div><div class="route-card-body"><small>${r.cat} · ${r.ids.length} 個地點</small><h3>${r.n}</h3><p>${r.text}</p><div class="route-card-meta">${I('clock',17)} ${r.time}</div><a href="#route/${r.id}" class="route-card-link">查看路線 ${I('arrow',18)}</a></div></article>`}
function filtered(){const q=state.query.trim().toLowerCase();return places.filter(p=>(state.cat==='全部'||p.cat===state.cat)&&(state.tag==='全部'||p.tags.includes(state.tag))&&(state.area==='全部'||p.area===state.area)&&(!q||[p.name,p.en,p.cat,p.area,p.address,p.desc,...p.tags].join(' ').toLowerCase().includes(q)))}
function mapPage(){let result=filtered();return `<main class="map-page"><div class="map-top"><div><span class="overline">探索澳門</span><h1>一座城，很多種綠色生活。</h1></div><p>從身邊的店、街角的故事開始，找到屬於你的路。</p></div><div class="map-workspace"><aside class="map-sidebar"><div class="sidebar-head"><div class="view-tabs"><button data-view="map" class="${state.view==='map'?'active':''}">${I('map',18)} 地圖</button><button data-view="list" class="${state.view==='list'?'active':''}">${I('list',18)} 列表</button></div>${searchBox(state.query,true)}</div><div class="filter-group"><h3>生活入口</h3><div class="filter-pills">${cats.map(c=>`<button data-cat="${c[0]}" class="${state.cat===c[0]?'active':''}">${c[0]}</button>`).join('')}</div></div><div class="filter-group"><h3>生態標籤</h3><div class="filter-tags">${['全部','食物','減廢','水','自然與生物多樣性','社區','文化','青年'].map(t=>`<button data-tag="${t}" class="${state.tag===t?'active':''}">${t}</button>`).join('')}</div></div><div class="filter-group"><h3>地區</h3><div class="filter-tags">${['全部','澳門半島','氹仔','路環'].map(a=>`<button data-area="${a}" class="${state.area===a?'active':''}">${a}</button>`).join('')}</div></div><div class="sidebar-count">找到 <strong>${result.length}</strong> 個地方 <button data-action="clear-filters">清除篩選</button></div></aside><div class="map-stage">${state.view==='map'?`<div id="real-map" aria-label="澳門地圖"></div><div class="map-fallback" aria-hidden="true"><div class="fallback-water"></div><div class="fallback-land land-one"></div><div class="fallback-land land-two"></div><div class="fallback-land land-three"></div><span>澳門半島</span></div><div id="fallback-pins"></div>`:`<div class="results-view"><div class="results-head"><h2>${state.query?`「${escapeHtml(state.query)}」的搜尋結果`:'探索地點'}</h2><span>${result.length} 個地點</span></div>${result.length?result.map(p=>placeRow(p)).join(''):`<div class="empty">${I('search',32)}<h3>暫時找不到符合的地方</h3><p>試試其他關鍵字，或清除篩選。</p><button class="outline-button" data-action="clear-filters">清除篩選</button></div>`}</div>`}${state.view==='map'&&state.selected&&result.some(p=>p.id===state.selected)?mapCard(places.find(p=>p.id===state.selected)):''}</div></div></main>`}
function placeRow(p){return `<article class="place-row"><img src="${p.img}" alt="${p.name}" loading="lazy"><div><div class="row-top"><small>${p.area} · ${p.cat}</small><h3>${p.name}</h3></div><p>${p.desc}</p><div class="row-tags">${p.tags.slice(0,2).map(tagChip).join('')}</div><span class="row-address">${I('pin',16)} ${p.address}</span></div><div class="row-actions"><button data-save="${p.id}" class="heart ${state.saved.has(p.id)?'saved':''}" aria-label="${state.saved.has(p.id)?'移除收藏':'加入收藏'}">${I('heart',21)}</button><a href="#place/${p.id}" aria-label="查看${p.name}">${I('arrow',20)}</a></div></article>`}
function mapCard(p){return `<article class="map-card"><button class="map-card-close" data-action="close-card" aria-label="關閉地點資訊">${I('close',17)}</button><img src="${p.img}" alt="${p.name}"><div><small>${p.area} · ${p.cat}</small><h3>${p.name}</h3><p>${p.desc}</p><div class="row-tags">${p.tags.slice(0,3).map(tagChip).join('')}</div><a href="#place/${p.id}">認識這個地方 ${I('arrow',18)}</a></div></article>`}
function placePage(id){let p=places.find(x=>x.id===id);if(!p)return `<main class="content-page"><a href="#map" class="back-link">${I('back',17)} 返回地圖</a><h1>找不到這個地點</h1></main>`;return `<main class="detail-page"><div class="detail-breadcrumb"><a href="#map">${I('back',17)} 返回地圖</a><span>/</span><span>${p.cat}</span><span>/</span><strong>${p.name}</strong></div><div class="detail-grid"><div class="detail-media"><img src="${p.img}" alt="${p.name}的環境"></div><div class="detail-main"><span class="overline">${p.area} · ${p.en}</span><h1>${p.name}</h1><div class="detail-tags"><span class="primary-tag">${p.cat}</span>${p.tags.map(tagChip).join('')}</div><p class="detail-quote">「${p.desc}」</p><div class="detail-info"><div>${I('pin',20)}<span>${p.area} ${p.address}</span></div><div>${I('clock',20)}<span>${p.hours}</span></div>${p.phone?`<div>${I('phone',20)}<span>${p.phone}</span></div>`:''}</div><div class="detail-actions"><button data-save="${p.id}" class="outline-button ${state.saved.has(p.id)?'saved':''}">${I('heart',18)} ${state.saved.has(p.id)?'已收藏':'加入收藏'}</button><button data-action="share" class="outline-button">${I('share',18)} 分享</button><a class="filled-link" href="#map?place=${p.id}">在地圖上查看 ${I('arrow',18)}</a></div></div></div><div class="detail-story"><div><span class="overline">地方的故事</span><h2>每個地方，<br>都有值得停下來的理由。</h2></div><p>${p.story}</p></div><div class="detail-bottom"><div class="section-heading"><div><h2>順路，再看看這些地方</h2></div><a class="text-link" href="#map">探索更多 ${I('arrow',18)}</a></div><div class="related-grid">${places.filter(x=>x.id!==p.id&&x.cat===p.cat).concat(places.filter(x=>x.id!==p.id&&x.cat!==p.cat)).slice(0,3).map(x=>`<a class="related" href="#place/${x.id}"><img src="${x.img}" alt=""><span>${x.area} · ${x.cat}</span><strong>${x.name}</strong>${I('arrow',17)}</a>`).join('')}</div></div></main>`}
function routesPage(){return `<main class="content-page"><div class="page-intro"><span class="overline">主題路線</span><h1>換一條路，<br><em>看見另一個澳門。</em></h1><p>從日常出發，跟著地方和人的故事慢慢走。</p></div><div class="route-grid large">${routes.map((r,i)=>routeCard(r,i)).join('')}</div><div class="page-note">步行時間為示意。出發前請確認地點開放時間與實際交通情況。</div></main>`}
function routePage(id){let r=routes.find(x=>x.id===id);if(!r)return `<main class="content-page"><a href="#routes" class="back-link">${I('back',17)} 所有路線</a><h1>找不到這條路線</h1></main>`;let idx=routes.indexOf(r);return `<main class="content-page route-detail"><a href="#routes" class="back-link">${I('back',17)} 所有路線</a><div class="route-hero route-art-${idx+1}"><span>${r.cat}</span><h1>${r.n}</h1><p>${r.text}</p><div>${I('pin',18)} ${r.ids.length} 個地點　 ${I('clock',18)} ${r.time}</div></div><div class="route-stops"><div><span class="overline">沿途停靠</span><h2>把每一步，走成一段認識。</h2></div><ol>${r.ids.map(id=>places.find(x=>x.id===id)).filter(Boolean).map((p,i)=>{return `<li><span class="stop-num">${String(i+1).padStart(2,'0')}</span><div><small>${p.area} · ${p.cat}</small><h3>${p.name}</h3><p>${p.desc}</p><a href="#place/${p.id}">認識地點 ${I('arrow',17)}</a></div></li>`}).join('')}</ol></div></main>`}
function storiesPage(){return `<main class="content-page"><div class="page-intro"><span class="overline">人物與地方故事</span><h1>看見人，<br><em>才看見地方的力量。</em></h1><p>一雙手、一塊土地、一個念頭，都能讓城市有新的可能。</p></div><div class="story-grid">${stories.map(s=>`<article class="story-card"><a href="#article/${encodeURIComponent(s.articleId||s.id)}"><img src="${escapeHtml(s.img)}" alt="${escapeHtml(s.n)}" loading="lazy"><span>${escapeHtml(s.tag)}</span><h2>${escapeHtml(s.n)}</h2><p>${escapeHtml(s.sub)}</p><strong>閱讀故事 ${I('arrow',18)}</strong></a></article>`).join('')}</div></main>`}
function articlePage(id){const a=articles.find(x=>x.id===id);if(!a)return `<main class="content-page"><a href="#stories" class="back-link">${I('back',17)} 返回人物故事</a><h1>這篇文章尚未發布</h1></main>`;const p=places.find(x=>x.id===a.place_id);return `<main class="article-page"><a href="#stories" class="back-link">${I('back',17)} 返回人物故事</a><div class="article-head"><span class="overline">${escapeHtml(a.category||'人物故事')}</span><h1>${escapeHtml(a.title)}</h1><p>${escapeHtml(a.subtitle)}</p></div>${a.img?`<img class="article-cover" src="${escapeHtml(a.img)}" alt="${escapeHtml(a.title)}">`:''}<article class="article-body">${escapeHtml(a.body).split(/\n\s*\n/).filter(Boolean).map(para=>`<p>${para.replace(/\n/g,'<br>')}</p>`).join('')}</article>${p?`<a class="article-place" href="#place/${p.id}">${I('pin',20)} <span>故事中的地方 <strong>${escapeHtml(p.name)}</strong></span>${I('arrow',19)}</a>`:''}</main>`}
function contributePage(){let steps=['基本資料','地點資訊','分類標籤','補充說明','完成'];return `<main class="contribute-page"><div class="contribute-intro"><span class="overline">參與投稿</span><h1>推薦一個好地方。</h1><p>把你珍惜的店、地方、人物或行動，分享給更多人。</p></div><div class="stepper">${steps.map((s,i)=>`<div class="${state.step===i+1?'active':''} ${state.step>i+1?'done':''}"><span>${state.step>i+1?I('check',15):i+1}</span><small>${s}</small></div>`).join('')}</div><form class="contribute-form" id="contribute-form">${contributeFields()}<div class="form-actions">${state.step>1&&state.step<5?`<button type="button" class="outline-button" data-action="prev-step">上一步</button>`:''}${state.step<5?`<button type="submit" class="filled-link">${state.step===4?'提交推薦':'下一步'} ${I('arrow',18)}</button>`:`<a href="#map" class="filled-link">繼續探索 ${I('arrow',18)}</a>`}</div></form><p class="form-note">推薦會先交由管理員審核，確認資料後才會公開顯示。</p></main>`}
function contributeFields(){let c=state.contribution;if(state.step===1)return `<span class="overline">先認識你的推薦</span><h2>你想推薦甚麼？</h2><p>選擇最貼近的類型，讓我們更了解這個地方的特色。</p><div class="type-grid">${[['地點／店舖','map'],['機構／團體','people'],['活動','clock'],['人物／故事','book'],['其他','leaf']].map(([label,icon])=>`<label class="type-option ${c.type===label?'selected':''}"><input type="radio" name="type" value="${label}" ${c.type===label?'checked':''} required>${I(icon,26)}<strong>${label}</strong></label>`).join('')}</div>`;if(state.step===2)return `<span class="overline">地點資訊</span><h2>它在哪裡？</h2><p>提供名字與大概位置，就能讓更多人找到它。</p><div class="field-grid"><label>名稱 <input name="name" value="${escapeHtml(c.name)}" placeholder="例如：街角修鞋店" required></label><label>地區 <select name="area" required><option value="">選擇地區</option>${['澳門半島','氹仔','路環'].map(a=>`<option ${c.area===a?'selected':''}>${a}</option>`).join('')}</select></label><label class="full">地址或活動地點 <input name="address" value="${escapeHtml(c.address)}" placeholder="街道及門牌，或容易辨認的位置" required></label></div>`;if(state.step===3)return `<span class="overline">分類標籤</span><h2>它和哪些生活議題有關？</h2><p>可選擇一個或多個標籤。</p><div class="checkbox-grid">${['食物','減廢','水','自然與生物多樣性','社區','文化','青年'].map(t=>`<label><input type="checkbox" name="tags" value="${t}" ${c.tags.includes(t)?'checked':''}><span>${t}</span></label>`).join('')}</div>`;if(state.step===4)return `<span class="overline">補充說明</span><h2>說說你為甚麼想推薦它。</h2><p>你看到的人、做過的事，往往是最動人的線索。</p><label class="full">推薦理由 <textarea name="description" rows="5" placeholder="寫下這個地方值得被看見的原因…" required>${escapeHtml(c.description)}</textarea></label><label class="full">圖片（選填） <input name="image" type="file" accept="image/jpeg,image/png,image/webp"></label><label class="full">聯絡方式（選填） <input name="contact" value="${escapeHtml(c.contact)}" placeholder="電郵或電話，方便日後聯繫"></label>${state.turnstileSiteKey?'<div id="turnstile-widget" class="turnstile-widget"></div>':''}`;return `<div class="success-state">${I('check',35)}<h2>謝謝你的分享。</h2><p>推薦已送達管理員，待核實後才會出現在地圖上。</p><button type="button" class="outline-button" data-action="new-contribution">再推薦一個地方</button></div>`}
function aboutPage(){return `<main class="about-page"><div class="about-hero"><div><span class="overline">關於綠門 GO</span><h1>一切都是<br><em>互相連繫的。</em></h1><p>從一個地方、一個故事開始，看見更綠色、更宜居的澳門。</p></div><img src="assets/macau-waterfront.png" alt="澳門海旁的樹蔭與城市景色"></div><div class="about-body"><div><h2>讓地圖，成為人與地方之間的一道門。</h2></div><div><p>綠門 GO 以澳門生態地圖為起點，連結身邊的綠色地點與在地故事。從修補、食物、自然到社區參與，我們相信改變可以由每一個小小的選擇開始。</p><p>這份互動示範依照提供的畫面重新設計，所列地點、聯絡方式與故事內容為展示用途，公開使用前應由團隊核實。</p><a href="#map" class="filled-link">開始探索 ${I('arrow',18)}</a></div></div></main>`}
function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function render(){let hash=location.hash.replace(/^#/,'')||'home';let [page,idWithQuery]=hash.split('/');let id=(idWithQuery||'').split('?')[0];if(!['home','map','routes','route','stories','article','place','contribute','about'].includes(page))page='home';state.page=page==='place'?'map':page==='route'?'routes':page==='article'?'stories':page;app.innerHTML=header()+(page==='home'?home():page==='map'?mapPage():page==='place'?placePage(id):page==='routes'?routesPage():page==='route'?routePage(id):page==='stories'?storiesPage():page==='article'?articlePage(decodeURIComponent(id)):page==='contribute'?contributePage():aboutPage())+foot()+`<div class="toast" role="status" aria-live="polite"></div>`;document.title=(page==='home'?'綠門 GO':page==='place'?(places.find(p=>p.id===id)?.name||'地點')+' · 綠門 GO':page==='article'?(articles.find(a=>a.id===id)?.title||'文章')+' · 綠門 GO':({map:'探索地圖',routes:'主題路線',route:'主題路線',stories:'人物故事',contribute:'參與投稿',about:'關於我們'}[page]||'綠門 GO')+' · 綠門 GO');if(page==='map'&&state.view==='map'&&state.configLoaded)setTimeout(initMap,0);if(page==='contribute'&&state.step===4&&state.turnstileSiteKey)setTimeout(renderTurnstile,0);window.scrollTo({top:0,behavior:'instant'})}
function renderTurnstile(){const target=document.getElementById('turnstile-widget');if(!target||target.dataset.rendered||!window.turnstile)return;window.turnstile.render(target,{sitekey:state.turnstileSiteKey,theme:'light'});target.dataset.rendered='true'}
function loadTurnstile(){if(document.querySelector('script[data-turnstile]'))return;const script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.async=true;script.defer=true;script.dataset.turnstile='true';script.onload=renderTurnstile;document.head.appendChild(script)}
function initMap(){let el=document.getElementById('real-map');if(!el)return;let result=filtered();if(window.L){try{leafletMap=L.map(el,{zoomControl:false,scrollWheelZoom:false}).setView([22.182,113.548],12);const tileUrl=state.maptilerKey?`https://api.maptiler.com/maps/basic-v2/{z}/{x}/{y}.png?key=${encodeURIComponent(state.maptilerKey)}`:'https://tile.openstreetmap.org/{z}/{x}/{y}.png';const tileAttribution=state.maptilerKey?'&copy; MapTiler &copy; OpenStreetMap contributors':'&copy; OpenStreetMap contributors';L.tileLayer(tileUrl,{attribution:tileAttribution,maxZoom:19}).addTo(leafletMap);L.control.zoom({position:'topright'}).addTo(leafletMap);result.forEach(p=>{let marker=L.marker([p.lat,p.lng],{icon:L.divIcon({className:'custom-marker',html:`<span class="marker-dot marker-${p.cat}">${I(cats.find(c=>c[0]===p.cat)?.[1]||'leaf',17)}</span>`,iconSize:[38,45],iconAnchor:[19,42]})}).addTo(leafletMap);marker.on('click',()=>{state.selected=p.id;document.querySelector('.map-card')?.remove();document.querySelector('.map-stage').insertAdjacentHTML('beforeend',mapCard(p))})});el.classList.add('loaded')}catch(e){console.warn('Map unavailable',e)}}else{let pins=document.getElementById('fallback-pins');if(pins)pins.innerHTML=result.map((p,i)=>`<button style="left:${25+(i*47)%58}%;top:${20+(i*31)%62}%" data-select="${p.id}" aria-label="${p.name}">${I(cats.find(c=>c[0]===p.cat)?.[1]||'leaf',16)}</button>`).join('')}}
function toast(message){let t=document.querySelector('.toast');if(!t)return;t.textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2800)}
document.addEventListener('click',e=>{let cat=e.target.closest('[data-cat]'),tag=e.target.closest('[data-tag]'),area=e.target.closest('[data-area]'),view=e.target.closest('[data-view]'),quick=e.target.closest('[data-quick]'),save=e.target.closest('[data-save]'),act=e.target.closest('[data-action]'),sel=e.target.closest('[data-select]');if(cat){state.cat=cat.dataset.cat;location.hash='#map';render()}else if(tag){state.tag=tag.dataset.tag;render()}else if(area){state.area=area.dataset.area;render()}else if(view){state.view=view.dataset.view;render()}else if(quick){state.cat=quick.dataset.quick;location.hash='#map';render()}else if(save){let id=save.dataset.save;state.saved.has(id)?state.saved.delete(id):state.saved.add(id);localStorage.setItem('green-go-saved',JSON.stringify([...state.saved]));render();toast(state.saved.has(id)?'已加入收藏':'已移除收藏')}else if(sel){state.selected=sel.dataset.select;render()}else if(act){switch(act.dataset.action){case'menu':state.mobileNav=!state.mobileNav;render();break;case'close-card':state.selected='';document.querySelector('.map-card')?.remove();break;case'clear-filters':state.cat='全部';state.tag='全部';state.area='全部';state.query='';render();break;case'share':navigator.clipboard?.writeText(location.href).then(()=>toast('連結已複製')).catch(()=>toast('請複製網址列中的連結'));break;case'search-focus':if(state.page!=='map'){location.hash='#map'}else document.querySelector('input[name="q"]')?.focus();break;case'language':toast('英文版本尚未提供，現正顯示繁體中文');break;case'prev-step':state.step--;render();break;case'new-contribution':state.step=1;state.contribution={type:'',name:'',address:'',tags:[],description:'',contact:''};render();break}}});
document.addEventListener('submit',async e=>{if(e.target.matches('[data-search-form]')){e.preventDefault();state.query=new FormData(e.target).get('q')?.trim()||'';state.view='list';location.hash='#map';render()}if(e.target.id==='contribute-form'){e.preventDefault();let fd=new FormData(e.target);if(state.step===1)state.contribution.type=fd.get('type')||'';if(state.step===2){state.contribution.name=fd.get('name')||'';state.contribution.area=fd.get('area')||'';state.contribution.address=fd.get('address')||''}if(state.step===3)state.contribution.tags=fd.getAll('tags');if(state.step===3&&state.contribution.tags.length===0){toast('請至少選擇一個標籤');return}if(state.step===4){state.contribution.description=fd.get('description')||'';state.contribution.contact=fd.get('contact')||'';const button=e.target.querySelector('button[type=submit]'),turnstileToken=fd.get('cf-turnstile-response')||'';if(state.turnstileSiteKey&&!turnstileToken){toast('請先完成人機驗證');return}button.disabled=true;button.textContent='正在提交…';try{const file=fd.get('image');if(file&&file.size){if(file.size>5_000_000)throw new Error('圖片不能超過 5 MB');const headers={'Content-Type':file.type};if(turnstileToken)headers['X-Turnstile-Token']=turnstileToken;const upload=await fetch('/api/upload?type=submission',{method:'POST',headers,body:file});const result=await upload.json();if(!upload.ok)throw new Error(result.error||'圖片上傳失敗');state.contribution.image=result.url;state.contribution.uploadGrant=result.uploadGrant}state.contribution.turnstileToken=turnstileToken;const response=await fetch('/api/submissions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(state.contribution)});const result=await response.json();if(!response.ok)throw new Error(result.error||'投稿未能送出');state.step=5;render()}catch(error){button.disabled=false;button.innerHTML=`提交推薦 ${I('arrow',18)}`;window.turnstile?.reset();toast(error.message)}return}state.step=Math.min(5,state.step+1);render()}});
async function loadContent(){try{const [p,r,a]=await Promise.all(['/api/places','/api/routes','/api/articles'].map(url=>fetch(url).then(async response=>{if(!response.ok)throw new Error('資料暫時無法讀取');return response.json()})));places=p;routes=r;articles=a;stories=a.map(item=>({n:item.title,sub:item.subtitle,tag:item.category,id:item.place_id,img:item.img||'assets/macau-waterfront.png',articleId:item.id}));render()}catch(error){console.warn('Using local preview content:',error.message)}try{const config=await fetch('/api/config').then(response=>response.ok?response.json():{});state.turnstileSiteKey=config.turnstileSiteKey||'';state.maptilerKey=config.maptilerKey||'';state.configLoaded=true;if(state.turnstileSiteKey)loadTurnstile();if(state.page==='contribute'||state.page==='map')render()}catch{state.configLoaded=true;if(state.page==='map')render()}}
window.addEventListener('hashchange',()=>{state.mobileNav=false;const q=location.hash.match(/place=([^&]+)/);if(q)state.selected=q[1];render()});render();loadContent();
